client_script:
frappe.ready(function () {
 const wf=frappe.web_form, REPORT=true, params=new URLSearchParams(location.search); let seq=0,lock=false,group=null,me=null;
 const has=f=>wf.fields_dict&&wf.fields_dict[f],setVal=(f,v)=>has(f)?wf.set_value(f,v):null,setDesc=(f,d)=>has(f)?wf.set_df_property(f,"description",d):null;
 const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const mapOf=()=>has("location")&&wf.fields_dict.location.map;
 const geo=(lat,lng)=>({type:"FeatureCollection",features:[{type:"Feature",properties:{point_type:"circlemarker",radius:10},geometry:{type:"Point",coordinates:[lng,lat]}}]});
 function pin(lat,lng,zoom=true){const map=mapOf();if(map&&window.L){if(me)me.remove();me=L.marker([lat,lng],{zIndexOffset:900}).addTo(map);if(zoom)map.setView([lat,lng],17);map.invalidateSize();}lock=true;setVal("location",JSON.stringify(geo(lat,lng)));setVal("latitude",lat);setVal("longitude",lng);setTimeout(()=>lock=false,700);apply(lat,lng);}
 function drawNearby(list){const map=mapOf();if(!map||!window.L)return;if(group)group.remove();group=L.layerGroup().addTo(map);(list||[]).forEach(s=>L.circleMarker([s.gps_lat,s.gps_lng],{radius:9,color:'#fff',weight:2,fillColor:'#f97316',fillOpacity:.95}).addTo(group).bindPopup('<b>'+esc(s.name)+'</b><br>'+s.distance_m+' m · '+s.tree_count+' trees<br><button class="hr-use-site" data-site="'+esc(s.site_id)+'">Use this spot</button>'));}
 function drawTrees(list){const map=mapOf();if(!map||!window.L)return;if(group)group.remove();group=L.layerGroup().addTo(map);(list||[]).forEach(t=>L.circleMarker([t.gps_lat||t.latitude,t.gps_lng||t.longitude],{radius:9,color:'#fff',weight:2,fillColor:'#16834b',fillOpacity:.95}).addTo(group).bindPopup('<b>'+esc(t.tree_id)+'</b><br>'+esc(t.species||'Tree')+' · '+t.distance_m+' m<br><button class="hr-use-tree" data-tree="'+esc(t.tree_id)+'">Report this tree</button>'));}
 document.addEventListener('click',e=>{let s=e.target.closest('.hr-use-site');if(s){e.preventDefault();setVal('existing_site',s.dataset.site);setVal('different_spot',0);return;}let t=e.target.closest('.hr-use-tree');if(t){e.preventDefault();setVal('tree',t.dataset.tree);setDesc('notes','Selected registered tree: '+t.dataset.tree);}});
 function apply(lat,lng){const n=++seq;frappe.call({method:'hasiruratha.citizen_api.locate',args:{lat,lng,for_report:REPORT?1:0}}).then(r=>{if(n!==seq)return;const d=r.message||{};setVal('area',d.area||'');setVal('road',d.road||'');setVal('address',d.address||'');if(REPORT){drawTrees(d.trees||[]);const t=(d.trees||[])[0];if(t&&!params.get('tree'))setVal('tree',t.tree_id);setDesc('notes',t?'Nearby tree: '+t.tree_id+' ('+t.distance_m+' m). Choose the exact tree marker if needed.':'No registered tree within 100 m. A new unverified tree record may be created for the team to check.');}else{drawNearby(d.nearby||[]);const s=(d.spots||[])[0];if(!params.get('existing_site'))setVal('existing_site',s?s.site_id:'');setDesc('existing_site',s?'Nearby spot: '+s.name+' ('+s.distance_m+' m, '+s.tree_count+' trees). Use it or confirm a different spot.':'No nearby registered spot found.');}}).catch(e=>console.error('Location lookup failed',e));}
 wf.on('location',(field,value)=>{if(lock||!value)return;try{const f=JSON.parse(value).features.find(x=>x.geometry.type==='Point');if(f){const c=f.geometry.coordinates;apply(c[1],c[0]);}}catch(e){}});
 function bindMap(){const map=mapOf();if(!map||!window.L)return setTimeout(bindMap,250);map.on('click',e=>pin(e.latlng.lat,e.latlng.lng,false));}
 function addSearch(){const loc=has('location')&&wf.fields_dict.location.wrapper;if(!loc)return;const box=document.createElement('div');box.className='hr-citizen-search';box.style.cssText='display:flex;gap:6px;margin:8px 0;flex-wrap:wrap';box.innerHTML='<input type="search" placeholder="Search area, road or landmark" style="flex:1;min-width:180px;padding:8px;border:1px solid #ccd8d1;border-radius:8px"><button type="button" style="padding:8px 12px;border:0;border-radius:8px;background:#1b5a43;color:white">Search</button>';loc.prepend(box);const input=box.querySelector('input'),button=box.querySelector('button');async function go(){const q=input.value.trim();if(!q)return;button.disabled=true;button.textContent='Searching…';try{const r=await fetch('https://nominatim.openstreetmap.org/search?format=json&q='+encodeURIComponent(q)+'&limit=1');const a=await r.json();if(a[0])pin(+a[0].lat,+a[0].lon,true);else frappe.msgprint(__('No location found.'));}catch(e){frappe.msgprint(__('Search is unavailable; tap the map to place the pin.'));}finally{button.disabled=false;button.textContent='Search';}}button.onclick=go;input.addEventListener('keydown',e=>{if(e.key==='Enter')go();});}
 addSearch();bindMap();
 const lat=params.get('lat'),lng=params.get('lng');if(lat&&lng&&Number.isFinite(+lat)&&Number.isFinite(+lng)){pin(+lat,+lng,true);if(REPORT&&params.get('tree'))setVal('tree',params.get('tree'));if(!REPORT&&params.get('existing_site'))setVal('existing_site',params.get('existing_site'));}else if(navigator.geolocation){navigator.geolocation.getCurrentPosition(p=>pin(p.coords.latitude,p.coords.longitude,true),()=>frappe.msgprint(__('Allow GPS or search/pin your location on the map.')),{enableHighAccuracy:true,timeout:12000});}
});
